"""Generates conftest.py with shared fixtures for all test clusters."""

from pathlib import Path

CONFTEST_TEMPLATE = '''\
# =============================================================
# Generated by TestGhost v2 — conftest.py
# Shared fixtures for all generated test files
# =============================================================

import pytest
import httpx


@pytest.fixture(scope="session")
def base_url() -> str:
    """Base URL of the application under test."""
    return "{base_url}"


@pytest.fixture(scope="session")
def client(base_url: str) -> httpx.Client:
    """Synchronous httpx client for integration tests."""
    with httpx.Client(base_url=base_url, timeout=30.0) as c:
        yield c


@pytest.fixture(scope="session")
def auth_headers() -> dict:
    """
    Stub: replace with real auth token logic.
    Example: return {{"Authorization": "Bearer <your-token>"}}
    """
    return {{}}
'''


def write_conftest(cluster_labels: list[str], base_url: str, output_dir: str) -> str:
    """Write conftest.py to the tests output directory. Returns the file path."""
    tests_dir = Path(output_dir) / "tests"
    tests_dir.mkdir(parents=True, exist_ok=True)

    conftest_path = tests_dir / "conftest.py"
    conftest_path.write_text(
        CONFTEST_TEMPLATE.format(base_url=base_url),
        encoding="utf-8",
    )
    return str(conftest_path)
